/* @lc app=leetcode id=3970 lang=kotlin */ class Solution { fun shortestPath(n: Int, edges: Array<IntArray>, labels: String, k: Int): Int = edges.groupBy { it[0] }.let { adj -> LongArray(n * (k + 1)) { Long.MAX_VALUE }.let { dist -> java.util.PriorityQueue<LongArray>(compareBy<LongArray> { it[0] }).let { pq -> dist.set(1, 0L).also { pq.add(longArrayOf(0L, 1L)) }.let { generateSequence { pq.poll() }.forEach { (d, s) -> if (d == dist[s.toInt()]) (s.toInt() / (k + 1)).also { u -> (s.toInt() % (k + 1)).also { r -> adj[u].orEmpty().forEach { e -> (if (labels[e[1]] == labels[u]) r + 1 else 1).also { nr -> if (nr <= k && d + e[2] < dist[e[1] * (k + 1) + nr]) dist.set(e[1] * (k + 1) + nr, d + e[2]).also { pq.add(longArrayOf(d + e[2], (e[1] * (k + 1) + nr).toLong())) } } } } } } }.let { (1..k).minOf { dist[(n - 1) * (k + 1) + it] }.let { if (it == Long.MAX_VALUE) -1 else it.toInt() } } } } } }